/* Prototipo de presentación. Todo el estado es local; no autentica ni mueve dinero. */
'use strict';
const paths={home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',leaf:'<path d="M20 4C10 2 3 7 5 15s15 4 15-11Z"/><path d="m4 21 11-11"/>',box:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 5v10l9 5 9-5V8M12 13v10M7 5l9 5"/>',deal:'<path d="m3 8 5-4 4 2 4-2 5 4-4 9-5 4-8-5-3-6 2-2Zm5-4 4 5 3-1M8 12l7 7M5 15l6 5"/>',chat:'<path d="M21 11a9 9 0 0 1-13 8l-5 2 1-6A9 9 0 1 1 21 11Z"/><path d="M8 10h8M8 14h5"/>',chart:'<path d="M3 3v18h18M6 16l5-6 4 3 6-8"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',heart:'<path d="M20 5c-3-3-7-1-8 1-1-2-5-4-8-1-5 5 1 10 8 16 7-6 13-11 8-16Z"/>',check:'<path d="m5 12 4 4L20 5"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4Z"/><path d="m8 11 3 3 5-5"/>',credit:'<path d="m13 2-9 12h7l-1 8 10-13h-7l0-7Z"/>',plus:'<path d="M12 4v16M4 12h16"/>',lock:'<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 15v3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',wallet:'<path d="M21 7H4a2 2 0 0 1 0-4h14v4M3 5v14a2 2 0 0 0 2 2h16V7M21 12h-6v5h6"/>',menu:'<path d="M3 5h18M3 12h18M3 19h18"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',logout:'<path d="M10 3H4v18h6m4-14 5 5-5 5M8 12h13"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z"/>',users:'<circle cx="9" cy="8" r="4"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M16 4a4 4 0 0 1 0 8m3 3a5 5 0 0 1 3 5"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.leaf}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'S/ '+Number(n).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2});
const button=(label,action,cls='primary',ico='arrow')=>`<button class="btn ${cls}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
const badge=(text,color='')=>`<span class="badge ${color}">${text}</span>`;
const initialProducts=[
 {id:9000,name:'Mandarina W. Murcott',category:'Cítricos',zone:'Huaura, Lima',short:'Diego T.',full:'Diego Torres',volume:4500,price:2.4,image:'mandarina.jpg',type:'cosecha',mode:'Recurrente',quality:'Calibre 63–68 mm',use:'Exportación',status:'Publicada',fresh:false},
 {id:9001,name:'Fresa San Andreas',category:'Berries',zone:'Huaral, Lima',short:'María P.',full:'María Paredes',volume:2800,price:4.8,image:'fresa.jpg',type:'cosecha',mode:'Spot',quality:'Primera · madurez comercial',use:'Mercado fresco',status:'Publicada',fresh:true},
 {id:9002,name:'Mandarina Tango',category:'Cítricos',zone:'Chincha, Ica',short:'Julio M.',full:'Julio Mendoza',volume:6000,price:2.1,image:'mandarina.jpg',type:'cosecha',mode:'Spot',quality:'Calibre 60–70 mm',use:'Industria',status:'Publicada',fresh:false},
 {id:9003,name:'Pulpa de fresa',category:'Pulpas',zone:'Lima, Lima',short:'Ana R.',full:'Ana Rojas',volume:1500,price:7.5,image:'fresa.jpg',type:'industrial',mode:'Recurrente',quality:'Congelada · sin azúcar',use:'Agroindustria',status:'Publicada',fresh:false},
 {id:9004,name:'Jugo de mandarina',category:'Jugos',zone:'Ica, Ica',short:'Luis G.',full:'Luis García',volume:3200,price:5.2,image:'mandarina.jpg',type:'industrial',mode:'Recurrente',quality:'Concentrado · refrigerado',use:'Agroindustria',status:'Publicada',fresh:true},
 {id:9005,name:'Fresa para proceso',category:'Berries',zone:'Huaura, Lima',short:'Elena H.',full:'Elena Huamán',volume:5000,price:3.1,image:'fresa.jpg',type:'cosecha',mode:'Spot',quality:'Selección industrial',use:'Industria',status:'En revisión',fresh:true}
];
const defaults=()=>({role:'comprador',credits:28,saved:[],unlocked:[],products:structuredClone(initialProducts),offers:[],messages:{},dealStage:0,outside:false,payment:0,rating:0,auto:false,providerProfile:{name:'Carlos Rodríguez',company:'Fundo Los Naranjos',email:'carlos@ejemplo.test'},profile:{name:'Bruno Gómez',company:'Fruit Fresh Export',email:'bruno@ejemplo.test'},planBuyer:'Plus',planSeller:'Crece',adminUsers:[{name:'Diego Torres',company:'Productor · Huaura',active:true},{name:'María Paredes',company:'Proveedora · Huaral',active:true},{name:'Bruno Gómez',company:'Comprador · Lima',active:true}]});
let state;try{state={...defaults(),...JSON.parse(localStorage.getItem('agrovio-propuesta-v1')||'null')}}catch{state=defaults()}
function save(){try{localStorage.setItem('agrovio-propuesta-v1',JSON.stringify(state))}catch{/* El recorrido también funciona si el navegador deshabilita almacenamiento. */}}
let query='',category='Todas',zone='Todas',mode='Todo',onlySaved=false,sort='recent',chartProduct='Mandarina',chartPeriod='6 semanas',chatId=9000,loginRole='comprador',starChoice=0;
const app=document.getElementById('app'),modal=document.getElementById('modal');let previousFocus=null,toastTimer;
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3600)}
function showModal(title,html){previousFocus=document.activeElement;modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Cerrar ventana">${icon('close')}</button></div>${html}`;if(!modal.open)modal.showModal()}
modal.addEventListener('close',()=>previousFocus?.isConnected&&previousFocus.focus());
function closeModal(){modal.close()}
const go=path=>{if(location.hash===`#/${path}`)render();else location.hash='/'+path};
function current(){return(location.hash||'#/inicio').slice(2).split('/')}
function titleFor(page){return{inicio:'Resumen',cosecha:'Mercado de cosechas',industrial:'Industrializados',guardados:'Mis guardados',publicaciones:'Mis cosechas',produccion:'Mis industrializados',ofertas:'Ofertas recibidas',tratos:'Mis tratos',movimientos:'Movimientos',chat:'Agrovio Chat',precios:'Histórico de precios',perfil:'Mi perfil',planes:'Mi suscripción',revision:'Revisión de publicaciones',usuarios:'Usuarios',custodia:'Custodia de pagos',detalle:'Detalle de publicación',trato:'Detalle del trato',publicar:'Nueva publicación'}[page]||'Resumen'}
function heading(title,sub,action=''){return`<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action||'<span class="date">21 octubre, 2026 · Datos de ejemplo</span>'}</div>`}
function stat(label,value,sub,ico='chart'){return`<article class="stat"><div class="stat-top">${label}${icon(ico)}</div><strong>${value}</strong><small>${sub}</small></article>`}
function navItems(){return state.role==='admin'?[['inicio','home','Vista general'],['revision','check','Revisión de publicaciones'],['usuarios','users','Usuarios'],['custodia','shield','Custodia de pagos'],['movimientos','wallet','Movimientos']]:state.role==='proveedor'?[['inicio','home','Resumen'],['publicaciones','leaf','Mis cosechas'],['produccion','box','Mis industrializados'],['ofertas','deal','Ofertas recibidas'],['tratos','deal','Mis tratos'],['chat','chat','Agrovio Chat'],['whatsapp','chat','Publicar por WhatsApp'],['movimientos','wallet','Movimientos'],['precios','chart','Histórico de precios']]:[['inicio','home','Resumen'],['cosecha','leaf','Mercado de cosechas'],['industrial','box','Industrializados'],['guardados','heart','Mis guardados'],['tratos','deal','Mis tratos'],['chat','chat','Agrovio Chat'],['precios','chart','Histórico de precios']]}
function shell(content,page){const admin=state.role==='admin',seller=state.role==='proveedor';const name=admin?'Equipo Agrovio':seller?state.providerProfile.name:state.profile.name;const items=navItems();const primary=admin?['inicio','revision','custodia','usuarios']:seller?['inicio','publicaciones','ofertas','tratos','chat','whatsapp']:['inicio','cosecha','industrial','tratos','chat'];const labels={chat:'Chat',whatsapp:'WhatsApp',inicio:'Inicio',publicaciones:'Mis productos',ofertas:'Ofertas de compra',tratos:'Mis tratos',cosecha:'Cosechas',industrial:'Industrializados',revision:'Revisar publicaciones',custodia:'Pagos'};const active=page==='detalle'?(seller?'publicaciones':'cosecha'):page==='trato'?'tratos':page;const link=([id,ico,label])=>'<a href="#/'+id+'" '+(active===id?'class="active" aria-current="page"':'')+'>'+icon(ico)+'<span>'+(labels[id]||label)+'</span></a>';return '<div class="shell role-'+state.role+'"><header class="site-header"><div class="header-main"><a class="brand" href="#/inicio" aria-label="Agrovio, inicio"><img src="assets/logo.png" alt=""><span>agrovio</span></a><span class="portal-caption">'+(admin?'Administración':seller?'Tu espacio para vender':'Tu espacio para comprar')+'</span><div class="top-actions"><label class="visually-hidden" for="role-select">Cambiar perfil del portal</label><select class="role-select" id="role-select">'+['comprador','proveedor','admin'].map(r=>'<option value="'+r+'" '+(state.role===r?'selected':'')+'>'+({comprador:'Comprador',proveedor:'Proveedor',admin:'Administrador'}[r])+'</option>').join('')+'</select><button class="icon-btn notification" data-action="notifications" aria-label="Ver notificaciones">'+icon('bell')+'</button><button class="user" data-action="profile"><span class="avatar">'+(admin?'AG':seller?'CR':'BG')+'</span><span class="user-text"><strong>'+esc(name)+'</strong><small>'+ (admin?'Equipo Agrovio':seller?esc(state.providerProfile.company):esc(state.profile.company))+'</small></span></button></div></div><div class="navigation-row"><nav class="main-navigation" aria-label="Navegación principal">'+items.filter(i=>primary.includes(i[0])).map(link).join('')+'<details class="more-navigation"><summary>'+icon('menu')+'<span>Más opciones</span></summary><div class="more-panel">'+items.filter(i=>!primary.includes(i[0])).map(link).join('')+(!admin?'<a href="#/planes">'+icon('credit')+'Mi plan</a>':'')+'<a href="#/perfil">'+icon('user')+'Mi perfil</a><a href="#/login">'+icon('logout')+'Salir</a></div></details></nav>'+(!admin?'<a class="header-resource" href="#/planes">'+icon(seller?'leaf':'credit')+(seller?'Mi plan: '+esc(state.planSeller):state.credits+' créditos disponibles')+'</a>':'<span class="header-resource">'+icon('shield')+'Gestión del portal</span>')+'</div></header><main class="workspace" id="content" tabindex="-1">'+content+'</main><footer class="footer"><span>© 2026 Agrovio · Conectamos el valor del campo.</span><button data-action="reset">Reiniciar recorrido</button></footer></div>';}
function productCard(p){const unlocked=state.unlocked.includes(p.id);return`<article class="product"><div class="product-image"><img src="assets/${p.image}" alt="${esc(p.name)}" loading="lazy">${badge(p.mode)}<button class="save ${state.saved.includes(p.id)?'saved':''}" data-action="save:${p.id}" aria-label="${state.saved.includes(p.id)?'Quitar de':'Agregar a'} guardados: ${esc(p.name)}" aria-pressed="${state.saved.includes(p.id)}">${icon('heart')}</button></div><div class="product-body"><span class="eyebrow">${p.category} · AGR-${p.id}</span><h3>${esc(p.name)}</h3><p>${icon('pin')}${esc(p.zone)}</p><div class="product-specs"><div><small>Volumen disponible</small><b>${p.volume.toLocaleString('es-PE')} kg</b></div><div><small>Proveedor</small><b>${esc(unlocked?p.full:p.short)}</b></div></div><div class="product-bottom"><strong>${money(p.price)} <small>/kg</small></strong><button data-action="detail:${p.id}" class="btn">Ver detalle ${icon('arrow')}</button></div></div></article>`}
function activities(){return`<div class="aside-card"><div class="section-title"><h3>Tu actividad</h3>${icon('clock')}</div>${[['deal','Tu oferta está en revisión','Mandarina · Hace 15 min'],['chat','Tienes una nueva respuesta','Negociación AGR-9000 · Hace 32 min'],['shield','Actualización de custodia','Trato AGR-9223 · Hace 1 h']].map(([i,t,s])=>`<div class="activity-item"><span class="activity-dot">${icon(i)}</span><div><strong>${t}</strong><small>${s}</small></div></div>`).join('')}</div>`}
function buyerHome(){return heading(`Buenos días, ${esc(state.profile.name.split(' ')[0])} <span style="font-size:25px">☀</span>`,'Encuentra productos, compara propuestas y da seguimiento a tus compras.')+`<div class="buyer-quick-links"><a href="#/cosecha">${icon('search')} Buscar productos ${icon('arrow')}</a><a href="#/tratos">${icon('deal')} Continuar mis tratos ${icon('arrow')}</a><a href="#/guardados">${icon('heart')} Ver mis guardados ${icon('arrow')}</a></div>`+`<section class="hero"><img class="hero-photo" src="assets/mandarina.jpg" alt="Cosecha de mandarinas"><div class="hero-copy"><span class="eyebrow">DEL CAMPO A TU PRÓXIMO NEGOCIO</span><h2>El origen de una<br>buena compra está aquí.</h2><p>Encuentra cosechas, conecta con proveedores y negocia con información clara.</p><a href="#/cosecha" class="btn light">Explorar el mercado ${icon('arrow')}</a></div></section><section class="stats" aria-label="Resumen comercial">${stat('Créditos disponibles',state.credits,'De 30 en tu ciclo actual','credit')}${stat('Negociaciones activas',state.offers.length+3,'Continúa tus conversaciones','deal')}${stat('Productos guardados',state.saved.length,'Tu próxima compra, más cerca','heart')}${stat('Tratos del ciclo','4','Consulta el detalle de tus compras','shield')}</section><div class="dashboard-grid"><section><div class="section-title"><div><h2>Oportunidades para tu negocio</h2><small>Oferta disponible, directo desde el origen.</small></div><a href="#/cosecha" class="btn text-btn">Ver todo ${icon('arrow')}</a></div><div class="tabs"><button class="active" data-action="home-tab:cosecha">Cosechas</button><button data-action="home-tab:industrial">Industrializados</button></div><div class="toolbar"><div class="search">${icon('search')}<input id="home-search" aria-label="Buscar en el mercado" placeholder="¿Qué producto estás buscando?"></div><button class="icon-btn" data-action="search-home" aria-label="Buscar">${icon('arrow')}</button></div><div class="product-grid" id="home-products">${state.products.filter(p=>p.status==='Publicada'&&p.type==='cosecha').slice(0,3).map(productCard).join('')}</div></section><aside class="dashboard-aside">${activities()}<div class="aside-card credit-card"><span class="eyebrow">TU PLAN, EN UN VISTAZO</span><h3 style="margin-top:10px">Conexiones que abren puertas.</h3><div class="credit-number">${state.credits}<span> / 30 créditos</span></div><p>Vencen al finalizar tu ciclo de 30 días. No se acumulan.</p><a class="btn text-btn" href="#/planes">Administrar mi plan ${icon('arrow')}</a></div><div class="aside-card help-card"><h3>Estamos de tu lado.</h3><p>Te acompañamos en tu próxima conexión.</p>${button('Conocer el proceso','help','light','chat')}<img src="assets/tigui_laptop.png" alt="Tigui, asistente de Agrovio"></div></aside></div>`}
function catalog(page){const type=page==='industrial'?'industrial':'cosecha';const saved=page==='guardados';return heading(titleFor(page),saved?'Tus oportunidades favoritas, reunidas en un solo lugar.':'Compra con contexto. Negocia con confianza.')+`<section class="catalog-head"><div><span class="eyebrow">EL CAMPO, MÁS CERCA</span><h2 style="margin-top:9px">${saved?'Una selección con potencial.':type==='industrial'?'Valor agregado desde el origen.':'Encuentra el lote que tu negocio necesita.'}</h2><p>Explorar y presentar ofertas no consume créditos de conexión.</p></div><div class="row">${icon('shield')}<small>Conexión por publicación<br><b>1 crédito · Sin cargos por ofertar</b></small></div></section><div class="catalog-layout"><aside class="filter-panel"><h3 class="row">${icon('filter')} Afinar búsqueda</h3><label>Categoría<select id="category">${['Todas',...(type==='industrial'?['Pulpas','Jugos']:['Cítricos','Berries'])].map(c=>`<option ${category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Región<select id="zone">${['Todas','Lima','Ica'].map(z=>`<option ${zone===z?'selected':''}>${z}</option>`).join('')}</select></label><label>Disponibilidad<select id="mode">${['Todo','Spot','Recurrente'].map(z=>`<option ${mode===z?'selected':''}>${z}</option>`).join('')}</select></label><label class="check-label"><input id="only-saved" type="checkbox" ${onlySaved||saved?'checked':''}>Solo mis guardados</label><button class="text-btn" data-action="clear-filters">Limpiar filtros</button></aside><section><div class="toolbar" style="margin-top:0"><div class="search">${icon('search')}<input id="catalog-search" aria-label="Buscar producto, zona o código" placeholder="Buscar producto, zona o código…" value="${esc(query)}"></div><select id="sort" aria-label="Ordenar productos"><option value="recent" ${sort==='recent'?'selected':''}>Más recientes</option><option value="price" ${sort==='price'?'selected':''}>Menor precio</option><option value="volume" ${sort==='volume'?'selected':''}>Mayor volumen</option></select></div><p class="list-heading" id="result-count"></p><div class="product-grid" id="catalog-products"></div></section></div>`}
function filteredProducts(){const page=current()[0];const type=page==='industrial'?'industrial':page==='guardados'?null:'cosecha';let list=state.products.filter(p=>p.status==='Publicada'&&(!type||p.type===type)&&(category==='Todas'||p.category===category)&&(zone==='Todas'||p.zone.includes(zone))&&(mode==='Todo'||p.mode===mode)&&(!(onlySaved||page==='guardados')||state.saved.includes(p.id))&&`${p.name} ${p.zone} AGR-${p.id}`.toLowerCase().includes(query.toLowerCase()));if(sort==='price')list.sort((a,b)=>a.price-b.price);if(sort==='volume')list.sort((a,b)=>b.volume-a.volume);if(sort==='recent')list.sort((a,b)=>b.id-a.id);return list}
function updateCatalog(){const target=document.getElementById('catalog-products');if(!target)return;const list=filteredProducts();target.innerHTML=list.length?list.map(productCard).join(''):`<div class="empty">${icon('search')}<h3>No encontramos coincidencias</h3><p>Prueba con otro producto o ajusta tus filtros.</p>${button('Limpiar filtros','clear-filters','',null)}</div>`;document.getElementById('result-count').textContent=`${list.length} publicaciones disponibles · Precios de referencia para negociar`}
function offerHistory(id){const rows=state.offers.filter(o=>o.productId===id);return rows.length?'<div class="divider"></div><h3>Tus propuestas</h3>'+rows.map(o=>'<div class="activity-item"><div><strong>'+money(o.price)+' / kg · '+o.quantity.toLocaleString('es-PE')+' kg</strong><small>'+esc(o.status)+'</small></div></div>').join(''):''}
function productDetail(id){const p=state.products.find(p=>p.id===Number(id));if(!p)return emptyPage();const unlocked=state.unlocked.includes(p.id),seller=state.role==='proveedor';return `<a href="#/${seller?'publicaciones':p.type==='industrial'?'industrial':'cosecha'}" class="btn text-btn">${icon('back')}Volver a ${seller?'mis publicaciones':'mercado'}</a><div class="detail-layout"><section><img class="detail-photo" src="assets/${p.image}" alt="${esc(p.name)}"><article class="card detail-info"><div class="row wrap">${badge(p.mode)}${badge(p.use,'gray')}<small>AGR-${p.id}</small></div><h1>${esc(p.name)}</h1><p class="muted row" style="font-size:13px">${icon('pin')}${esc(p.zone)} · ${esc(seller||unlocked?p.full:p.short)}</p><div class="spec-grid">${[['Volumen disponible',p.volume.toLocaleString('es-PE')+' kg'],['Precio referencial',money(p.price)+'/kg'],['Especificaciones',p.quality],['Disponibilidad','Inmediata · Coordinar despacho'],['Destino sugerido',p.use],['Modalidad',p.mode]].map(([l,v])=>`<div><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="divider"></div><h3>Condiciones del lote</h3><p class="muted" style="font-size:13px">Producto disponible en origen. Precio, volumen, selección y condiciones de recojo sujetos a acuerdo entre las partes. Fotografías ilustrativas del producto.</p><div class="notice">${icon('shield')}Puedes solicitar una verificación de calidad en campo antes de decidir. Servicio adicional sujeto a cotización.</div></article></section><aside class="stack" style="align-content:start">${seller?`<article class="card"><h2>Gestionar publicación</h2><p class="muted">Estado: ${badge(p.status)}</p><div class="notice">${icon('clock')}${p.fresh?'Dentro de las primeras 24 horas: puedes editar.':'La ventana de edición de 24 horas finalizó. Solo puedes cancelar.'}</div>${(p.fresh||p.status==='Requiere corrección')&&p.status!=='Cancelada'?button('Editar publicación',`edit:${p.id}`,'primary full','plus'):''}<div style="margin-top:12px">${p.status!=='Cancelada'?button('Cancelar publicación',`cancel:${p.id}`,'danger full','close'):''}</div><small>Cancelar no devuelve el cupo consumido del ciclo.</small></article>`:`<article class="card"><div class="section-title"><h2>Haz una oferta</h2>${icon('deal')}</div><p class="muted" style="font-size:12px">Acuerda el precio y el volumen. Ofertar es gratis.</p><form id="offer-form" data-id="${p.id}"><div class="form-grid"><label>Precio por kg (S/)<input id="offer-price" name="price" type="number" min="0.01" step="0.01" value="${p.price}" required></label><label>Cantidad (kg)<input id="offer-quantity" name="quantity" type="number" min="1" max="${p.volume}" step="1" value="${p.volume}" required></label></div><label>Condiciones de tu propuesta<textarea name="conditions" maxlength="500" placeholder="Fecha de recojo, selección, transporte…"></textarea></label><div class="offer-total"><span>Monto de la oferta</span><strong id="offer-total">${money(p.price*p.volume)}</strong></div><button class="btn primary full" type="submit">Enviar oferta ${icon('arrow')}</button><small>Sin consumo de créditos. El proveedor revisará tu propuesta.</small></form>${offerHistory(p.id)}</article><article class="card"><h3 class="row">${icon(unlocked?'check':'lock')}${unlocked?'Conexión habilitada':'Conecta con el proveedor'}</h3>${unlocked?`<p><b>${esc(p.full)}</b><br>Contacto habilitado solo para AGR-${p.id}.</p><div class="notice">Contacto ficticio para presentación. En producción aparecerán aquí el teléfono y WhatsApp verificados.</div>${button('Abrir conversación',`chat:${p.id}`,'primary full','chat')}`:`<p class="muted" style="font-size:12px">Utiliza 1 crédito para desbloquear esta publicación. Puedes hacerlo ahora o después de acordar el precio.</p>${button('Desbloquear · 1 crédito',`unlock:${p.id}`,'primary full','credit')}<small style="display:block;margin-top:12px">Tienes ${state.credits} créditos. No desbloquea otras publicaciones del mismo proveedor.</small>`}</article>`}</aside></div>`}
function supplierProducts(list){return '<div class="supplier-products">'+list.map(p=>'<article class="supplier-product"><img src="assets/'+p.image+'" alt="'+esc(p.name)+'"><div class="supplier-product-info"><div class="row wrap">'+badge(p.status,p.status==='En revisión'?'amber':p.status==='Cancelada'?'gray':'')+'<small>AGR-'+p.id+'</small></div><h3>'+esc(p.name)+'</h3><p>'+esc(p.zone)+' · '+p.volume.toLocaleString('es-PE')+' kg</p><strong>'+money(p.price)+' <small>/ kg</small></strong><small class="edit-hint">'+(p.status==='En revisión'?'Esperando revisión de Agrovio':p.fresh?'Todavía puedes editar esta publicación':'Edición finalizada · Puedes consultar o cancelar')+'</small></div>'+button('Ver producto','detail:'+p.id,'','arrow')+'</article>').join('')+'</div>';}
function whatsappPage(){return heading('Publica desde WhatsApp','Una forma sencilla de registrar tus productos, paso a paso.')+'<div class="whatsapp-layout"><section class="card"><span class="badge">'+icon('chat')+'PARA PROVEEDORES</span><h2 style="margin-top:18px">Responde, revisa y confirma.</h2><p>El asistente te hará preguntas cortas sobre tu producto. No necesitas escribir una publicación completa.</p><div class="timeline"><div class="timeline-item done"><strong>1. Entra desde tu cuenta</strong><small>Así podemos asociar el producto a tu perfil y verificar tu plan y cupos.</small></div><div class="timeline-item"><strong>2. Completa los datos y envía fotos</strong><small>Elige las opciones e indica producto, cantidad, precio, zona y disponibilidad.</small></div><div class="timeline-item"><strong>3. Revisa el resumen</strong><small>Confirma los datos o vuelve al menú para empezar otra vez.</small></div><div class="timeline-item"><strong>4. Agrovio revisa tu publicación</strong><small>Después de confirmar, verás tu producto en revisión en el portal.</small></div></div><div class="notice">'+icon('chat')+'El número oficial y la conexión real de WhatsApp están pendientes. Puedes preparar tu publicación desde aquí mientras se habilita el servicio.</div>'+button('Preparar mi publicación','publish','primary full','plus')+'<a href="#/publicaciones" class="btn text-btn full" style="margin-top:12px">Ver mis productos '+icon('arrow')+'</a></section><aside class="whatsapp-preview"><header class="row"><span class="avatar">'+icon('leaf')+'</span><div><h3>Agrovio · Publicaciones</h3><small>Ejemplo del recorrido por WhatsApp</small></div></header><div class="whatsapp-messages"><div class="wa-bubble">Hola, Carlos. Vamos a publicar tu producto. ¿Qué quieres vender?<div class="wa-options"><span>Cosecha</span><span>Industrializado</span></div></div><div class="wa-bubble mine">Cosecha</div><div class="wa-bubble">¿Qué producto tienes y cuántos kilos hay disponibles?</div><div class="wa-bubble mine">Mandarina · 4.500 kg</div><div class="wa-bubble">Indica el precio por kilo, la zona y envía las fotos del producto.</div><div class="wa-bubble mine">S/ 2,40 por kg · Huaura, Lima</div><div class="wa-bubble"><strong>Revisa tu publicación</strong><p>Mandarina<br>4.500 kg · S/ 2,40 por kg<br>Huaura, Lima</p><div class="wa-options"><span>Confirmar</span><span>Volver al menú</span></div></div><div class="wa-bubble">Al confirmar, tu producto se enviará a revisión de Agrovio.</div></div></aside></div>';}
function sellerHome(){const pending=allOffers().filter(o=>o.status==='Pendiente').length,review=state.products.filter(p=>p.status==='En revisión').length;return heading('Hola, '+esc(state.providerProfile.name.split(' ')[0])+'. ¿Qué quieres hacer hoy?','Publica tus productos y revisa quién quiere comprarte.')+'<section class="seller-welcome"><div><span class="eyebrow">DEL CAMPO A MÁS COMPRADORES</span><h2>Vender empieza<br>por mostrar lo que tienes.</h2><p>Te acompañamos paso a paso. Elige cómo quieres publicar.</p><div class="button-group">'+button('Publicar un producto','publish','primary','plus')+button('Publicar por WhatsApp','whatsapp','','chat')+'</div></div><img src="assets/campo.jpg" alt="Fresas listas para comercializar"></section><section class="task-grid" aria-label="Tus tareas principales"><a class="task-card" href="#/publicaciones"><span class="task-icon">'+icon('leaf')+'</span><div><h3>Mis productos</h3><p>Mira lo que publicaste y su estado.</p><strong>'+state.products.filter(p=>p.status==='Publicada').length+' publicados</strong></div>'+icon('arrow')+'</a><a class="task-card" href="#/ofertas"><span class="task-icon">'+icon('deal')+'</span><div><h3>¿Quién quiere comprar?</h3><p>Revisa el precio y la cantidad que te ofrecen.</p><strong>'+pending+' ofertas por responder</strong></div>'+icon('arrow')+'</a><a class="task-card" href="#/tratos"><span class="task-icon">'+icon('shield')+'</span><div><h3>Mis tratos y pagos</h3><p>Confirma tus acuerdos y consulta tus pagos.</p><strong>Ver el estado de mis tratos</strong></div>'+icon('arrow')+'</a></section><div class="seller-status"><span class="task-icon">'+icon('clock')+'</span><div><h3>'+ (review?review+' publicación'+(review===1?' está':'es están')+' en revisión':'Tus publicaciones están al día')+'</h3><p>'+ (review?'Agrovio está revisando la información. Te avisaremos cuando se publique.':'Puedes publicar otro producto o revisar tus ofertas de compra.')+'</p></div><a href="#/publicaciones" class="btn">Ver mis productos '+icon('arrow')+'</a></div><div class="section-title"><div><h2>Tus productos más recientes</h2><small>Revisa el estado de cada publicación.</small></div><a class="text-btn btn" href="#/publicaciones">Ver todos '+icon('arrow')+'</a></div>'+supplierProducts(state.products.slice(-3))+'<div class="notice">'+icon('clock')+'Puedes editar tu producto durante las primeras 24 horas desde que se publica. Después puedes cancelarlo; el cupo utilizado no se devuelve.</div>';}
function publicationTable(type){const list=state.products.filter(p=>p.type===type);return`<div class="card table-card table-wrap"><table><thead><tr><th>Publicación</th><th>Volumen</th><th>Precio / kg</th><th>Estado</th><th>Edición</th><th>Acciones</th></tr></thead><tbody>${list.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>AGR-${p.id} · ${esc(p.zone)}</small></td><td>${p.volume.toLocaleString('es-PE')} kg</td><td>${money(p.price)}</td><td>${badge(p.status,p.status==='En revisión'?'amber':p.status==='Cancelada'?'gray':'')}</td><td><small>${p.fresh?'Disponible · primeras 24 h':'Ventana finalizada'}</small></td><td><button data-action="detail:${p.id}">Ver detalle</button></td></tr>`).join('')}</tbody></table></div>`}
function publications(page){return heading(page==='produccion'?'Mis productos industrializados':'Mis productos','Aquí puedes ver, editar o cancelar tus publicaciones.',button('Publicar producto','publish','primary','plus'))+'<div class="section-title"><div class="tabs"><a class="btn '+(page==='publicaciones'?'primary':'')+'" href="#/publicaciones">Cosechas</a><a class="btn '+(page==='produccion'?'primary':'')+'" href="#/produccion">Industrializados</a></div>'+button('Publicar por WhatsApp','whatsapp','','chat')+'</div>'+supplierProducts(state.products.filter(p=>p.type===(page==='produccion'?'industrial':'cosecha')))+'<div class="notice">'+icon('shield')+'Todas las publicaciones pasan por revisión. Si no renuevas tu plan, se eliminan.</div>';}
function publishForm(editId){const p=state.products.find(p=>p.id===Number(editId));return heading(p?'Editar publicación':'Dale un nuevo destino a tu producto.','Completa la ficha. Agrovio revisará la información antes de mostrarla.')+`<div class="detail-layout"><article class="card"><form id="publish-form" data-id="${p?p.id:''}"><div class="form-grid"><label class="wide">Nombre del producto<input name="name" required maxlength="70" placeholder="Ej. Mandarina W. Murcott" value="${esc(p?.name||'')}"></label><label>Tipo<select name="type"><option value="cosecha">Cosecha</option><option value="industrial" ${p?.type==='industrial'?'selected':''}>Industrializado</option></select></label><label>Categoría<select name="category">${['Cítricos','Berries','Pulpas','Jugos'].map(c=>`<option ${p?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Volumen (kg)<input name="volume" type="number" min="1" max="10000000" step="1" required value="${p?.volume||''}"></label><label>Precio referencial (S/ por kg)<input name="price" type="number" min="0.01" max="1000000" step="0.01" required value="${p?.price||''}"></label><label>Zona de origen<input name="zone" required maxlength="80" placeholder="Distrito, región" value="${esc(p?.zone||'')}"></label><label>Modalidad<select name="mode"><option>Spot</option><option ${p?.mode==='Recurrente'?'selected':''}>Recurrente</option></select></label><label class="wide">Especificaciones<input name="quality" required maxlength="150" placeholder="Calibre, calidad, conservación…" value="${esc(p?.quality||'')}"></label><label class="wide">Fotografía de referencia (opcional)<input type="file" name="photo" id="photo-input" accept="image/jpeg,image/png,image/webp"><small>Máximo 3 MB. Se muestra como vista previa local; no se sube a ningún servidor.</small><span id="photo-preview"></span></label></div><div class="notice">${icon('clock')}Tu publicación será revisada por Agrovio antes de aparecer en el mercado. Te notificaremos el resultado. El plazo de revisión está por confirmar.</div><button type="submit" class="btn primary">${p?'Guardar y enviar a revisión':'Enviar a revisión'} ${icon('arrow')}</button></form></article><aside><article class="card"><span class="eyebrow">UNA FICHA QUE CONECTA</span><h2 style="margin-top:13px">Información clara.<br>Mejores oportunidades.</h2><div class="timeline"><div class="timeline-item done"><strong>Completa tu publicación</strong><small>Producto, volumen, precio y zona.</small></div><div class="timeline-item"><strong>Agrovio revisa</strong><small>También para publicaciones por WhatsApp.</small></div><div class="timeline-item"><strong>Empieza a recibir ofertas</strong><small>Revisa y negocia desde tu portal.</small></div></div><small>El ciclo cuenta las publicaciones utilizadas. Cancelar no recupera el cupo.</small></article><article class="aside-card" style="margin-top:20px"><h3>¿Prefieres WhatsApp?</h3><p>El equipo podrá ayudarte a crear la ficha. Se someterá a la misma revisión.</p>${button('Ver cómo funciona','whatsapp','', 'chat')}</article></aside></div>`}
function allOffers(){const base=[{id:100,productId:9000,price:2.3,quantity:4500,conditions:'Recojo en origen esta semana.',status:'Pendiente'},{id:101,productId:9001,price:4.6,quantity:2000,conditions:'Entrega coordinada.',status:'Pendiente'},{id:102,productId:9002,price:2,quantity:5000,conditions:'Pago por Agrovio.',status:'Pendiente'}];return [...state.offers,...base.filter(o=>!state.offers.some(saved=>saved.id===o.id))]}
function offers(){const offers=allOffers();return heading('Mira quién quiere comprarte.','Compara el precio y la cantidad. Puedes aceptar, proponer otro precio o rechazar.')+'<div class="offer-list">'+offers.map(o=>{const p=state.products.find(p=>p.id===o.productId);return '<article class="offer-card"><div class="row"><img src="assets/'+p.image+'" alt="'+esc(p.name)+'"><div><small>Tu producto · AGR-'+p.id+'</small><h2>'+esc(p.name)+'</h2><p>Propuesta de Bruno G.</p></div></div><div class="offer-figures"><div><small>Te ofrecen por kg</small><strong>'+money(o.price)+'</strong></div><div><small>Quieren comprar</small><strong>'+o.quantity.toLocaleString('es-PE')+' kg</strong></div><div><small>Monto de la propuesta</small><strong>'+money(o.price*o.quantity)+'</strong></div></div><div class="row between wrap">'+badge(o.status,o.status==='Pendiente'?'amber':'gray')+button(o.status==='Pendiente'?'Revisar y responder':'Ver respuesta','respond:'+o.id,o.status==='Pendiente'?'primary':'','arrow')+'</div></article>';}).join('')+'</div><div class="notice">'+icon('deal')+'Aceptar una oferta acuerda el precio y la cantidad. Después, ambas partes deben confirmar el cierre del trato.</div>';}
function dealStatus(){return state.outside?'Registrado por fuera':state.dealStage<3?['Por iniciar','Pendiente del comprador','Confirmación final del vendedor'][state.dealStage]:['Pendiente de transferencia','Pago recibido','Pago liberado'][state.payment]}
function deals(){return heading('Acuerdos claros, relaciones que crecen.','Sigue tus negociaciones y el avance de cada operación.')+`<section class="stats">${stat('En negociación',state.offers.length+3,'Propuestas de compra','chat')}${stat('Por confirmar',state.dealStage<3&&!state.outside?1:0,'Confirma las condiciones del trato','deal')}${stat('Pago en proceso',state.dealStage===3&&state.payment<2&&!state.outside?1:0,'Fondos aún no liberados','wallet')}${stat('Comisión Agrovio','1%','Para cada parte · Cierre en Agrovio','shield')}</section><div class="card table-card table-wrap"><table><thead><tr><th>Operación</th><th>Contraparte</th><th>Volumen</th><th>Monto del trato</th><th>Estado</th><th></th></tr></thead><tbody><tr><td><strong>Mandarina W. Murcott</strong><small>AGR-9223 · 21 oct, 2026</small></td><td>${state.role==='proveedor'?'Bruno Gómez':'Diego T.'}</td><td>5.000 kg</td><td>${money(22500)}</td><td>${badge(dealStatus(),state.payment===2||state.outside?'':'amber')}</td><td><a class="btn" href="#/trato/9223">Ver operación ${icon('arrow')}</a></td></tr><tr><td><strong>Fresa San Andreas</strong><small>AGR-9211 · 15 oct, 2026</small></td><td>${state.role==='proveedor'?'Bruno Gómez':'María P.'}</td><td>2.000 kg</td><td>${money(9600)}</td><td>${badge('Completado')}</td><td><button data-action="completed">Ver resumen</button></td></tr></tbody></table></div>`}
function dealDetail(){const seller=state.role==='proveedor',admin=state.role==='admin',closed=state.dealStage===3;return`<a href="#/tratos" class="text-btn btn">${icon('back')}Volver a mis tratos</a>`+heading('Un acuerdo, cada paso a la vista.','AGR-9223 · Mandarina W. Murcott · Datos ilustrativos')+`<div class="detail-layout"><div class="stack"><article class="card"><div class="section-title"><h2>Detalle de la operación</h2>${badge(dealStatus(),'amber')}</div><div class="spec-grid"><div><small>Producto</small><strong>Mandarina W. Murcott</strong></div><div><small>Volumen acordado</small><strong>5.000 kg</strong></div><div><small>Precio por kg</small><strong>S/ 4,50</strong></div><div><small>Origen</small><strong>Huaura, Lima</strong></div></div><div class="divider"></div><h3>Resumen económico</h3>${[['Monto del trato',22500],['Comisión comprador (1%)',state.outside?0:225],['Comisión proveedor (1%)',state.outside?0:225]].map(([l,v])=>`<div class="money-line"><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}<div class="money-line total"><span>Paga el comprador</span><span>${money(state.outside?22500:22725)}</span></div><div class="money-line total"><span>Recibe el proveedor</span><span>${money(state.outside?22500:22275)}</span></div><small>Cálculo ilustrativo, sin impuestos adicionales sobre comisiones. Tratamiento tributario y moneda final por definir.</small>${state.outside?'<div class="notice">Registro básico de un acuerdo externo. Agrovio no cobra comisión ni administra el pago.</div>':''}</article><article class="card"><h3>Confirmación del acuerdo</h3><div class="timeline">${['El proveedor solicita el cierre','El comprador confirma','El proveedor confirma el cierre final'].map((t,i)=>`<div class="timeline-item ${state.dealStage>i?'done':''}"><strong>${t}</strong><small>${state.dealStage>i?'Confirmado en la demo':'Pendiente'}</small></div>`).join('')}</div>${!state.outside&&!closed?((state.dealStage===0&&seller)||(state.dealStage===1&&!seller&&!admin)||(state.dealStage===2&&seller)?button(['Solicitar cierre','Confirmar condiciones','Confirmar cierre final'][state.dealStage],'confirm-deal','primary','check'):`<div class="notice">${icon('clock')}Esperando al ${state.dealStage===1?'comprador':'proveedor'}. Puedes cambiar de vista en la barra superior para recorrer el proceso.</div>`):''}${!closed&&!state.outside?`<div style="margin-top:12px">${button('Acordamos por fuera','outside','','arrow')}</div>`:''}</article></div><aside class="stack" style="align-content:start"><article class="card"><h2>Estado del pago</h2>${state.outside?'<p>El pago se gestiona directamente entre las partes.</p>':`<div class="timeline">${[['Transferencia del comprador','Pendiente de confirmar por Agrovio'],['Dinero recibido por Agrovio','Administración verifica el ingreso'],['Pago liberado al proveedor','Administración confirma la transferencia']].map(([t,s],i)=>`<div class="timeline-item ${(i===0&&state.payment>=1)||(i===1&&state.payment>=1)||(i===2&&state.payment===2)?'done':''}"><strong>${t}</strong><small>${s}</small></div>`).join('')}</div>${!closed?'<div class="notice">Completa las tres confirmaciones del trato antes de iniciar el pago.</div>':state.payment===0?'<div class="notice amber">Pago en proceso. No se mostrarán cuentas bancarias hasta que Agrovio configure los datos reales.</div>':state.payment===1?'<div class="notice">Agrovio confirmó el ingreso. Pendiente de liberar el pago al proveedor.</div>':'<div class="notice">El pago fue liberado al proveedor en esta demostración.</div>'}`}${admin?button('Gestionar custodia','custody','primary full','shield'):button('Abrir conversación','chat:9000','full','chat')}</article>${state.payment===2?`<article class="card"><h3>Las buenas relaciones se construyen.</h3><p>Comparte tu experiencia al finalizar el trato.</p>${state.rating?badge('Tu calificación: '+state.rating+' / 5'):button('Calificar operación','rate','primary full','star')}<small>Agrovio también revisa la confiabilidad antes y después de la operación.</small></article>`:''}</aside></div>`}
function chat(){const p=state.products.find(p=>p.id===chatId)||state.products[0],unlocked=state.unlocked.includes(p.id)||state.role==='proveedor';const messages=state.messages[p.id]||[];return heading('Una conversación puede cambiar tu campaña.','Negocia en la plataforma y conserva el contexto de cada acuerdo.')+`<div class="chat-layout"><aside class="chat-list"><h3>Conversaciones</h3>${state.products.filter(p=>p.id===9000||state.unlocked.includes(p.id)).slice(0,5).map(x=>`<button data-action="chat-select:${x.id}" class="conversation ${x.id===p.id?'active':''}"><span class="avatar">${x.short.slice(0,1)}${x.short.split(' ')[1]?.[0]||'P'}</span><span><strong>Negociación AGR-${x.id}</strong><small>${esc(x.name)}</small></span></button>`).join('')}</aside><section class="chat-main"><header class="chat-header row between"><div class="row"><span class="avatar">${icon('chat')}</span><div><h3>${esc(unlocked?p.full:p.short)}</h3><small>AGR-${p.id} · ${esc(p.name)}</small></div></div>${badge('En negociación','blue')}</header><div class="messages" id="messages"><div class="message">Hola, el lote sigue disponible. Podemos revisar precio, volumen y fecha de recojo.<small>Proveedor · 09:05 · Mensaje de ejemplo</small></div><div class="message mine">Gracias. Me interesa coordinar una compra para esta semana.<small>Tú · 09:10 · Mensaje de ejemplo</small></div>${messages.map(m=>`<div class="message mine">${esc(m)}<small>Tú · Demo local</small></div>`).join('')}</div>${unlocked?`<div class="chat-agreement"><small><b>¿Ya acordaron las condiciones?</b><br>Continúa con el cierre y las confirmaciones.</small><a href="#/trato/9223" class="btn primary">Revisar trato ${icon('arrow')}</a></div><form class="chat-input" id="chat-form"><input name="message" required maxlength="1000" aria-label="Mensaje" placeholder="Escribe un mensaje…" autocomplete="off"><button class="icon-btn primary" aria-label="Enviar mensaje" type="submit">${icon('arrow')}</button></form>`:`<div class="notice" style="margin:20px">${icon('lock')}Para escribir en el chat y ver el contacto, desbloquea esta publicación con 1 crédito. Puedes negociar primero desde las ofertas.</div><div style="padding:0 20px 20px">${button('Desbloquear · 1 crédito',`unlock:${p.id}`,'primary','credit')}</div>`}</section></div>`}
function chartSVG(product,period){const berry=product==='Fresa',long=period==='3 meses';const points=berry?(long?'0,190 100,170 200,180 300,115 400,125 500,65 600,85 700,35':'0,170 100,190 200,145 300,160 400,90 500,105 600,65 700,45'):(long?'0,200 100,180 200,195 300,140 400,150 500,100 600,120 700,70':'0,195 100,160 200,175 300,110 400,130 500,80 600,95 700,40');return`<svg class="chart" viewBox="0 0 700 240" role="img" aria-label="${product}: tendencia de precios ilustrativa de ${period}" preserveAspectRatio="none"><defs><linearGradient id="chart-fill-${berry?'b':'a'}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#8ab56d" stop-opacity=".28"/><stop offset="100%" stop-color="#8ab56d" stop-opacity="0"/></linearGradient></defs>${[40,100,160,220].map(y=>`<line x1="0" y1="${y}" x2="700" y2="${y}" stroke="#e6ece2" stroke-dasharray="4 5"/>`).join('')}<polygon points="0,240 ${points} 700,240" fill="url(#chart-fill-${berry?'b':'a'})"/><polyline points="${points}" fill="none" stroke="#397f4d" stroke-width="3" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></svg>`}
function prices(){const price=chartProduct==='Fresa'?4.8:2.4;return heading('El contexto también es una ventaja.','Consulta tendencias para tomar decisiones comerciales mejor informadas.')+`<div class="notice">${icon('chart')}Datos ilustrativos de operaciones de demostración; no representan cotizaciones reales de mercado.</div><div class="card"><div class="section-title"><div><h2>${chartProduct} · Precio por kilogramo</h2><small>Promedio de operaciones cerradas en Agrovio · S/ por kg</small></div><div class="row"><select id="chart-product" aria-label="Producto"><option ${chartProduct==='Mandarina'?'selected':''}>Mandarina</option><option ${chartProduct==='Fresa'?'selected':''}>Fresa</option></select><select id="chart-period" aria-label="Periodo"><option ${chartPeriod==='6 semanas'?'selected':''}>6 semanas</option><option ${chartPeriod==='3 meses'?'selected':''}>3 meses</option></select></div></div><div class="row between"><strong style="font-size:35px;letter-spacing:-1px">${money(price)}<small> / kg</small></strong>${badge(chartPeriod==='3 meses'?'+12,4% en el período':'+8,2% en el período')}</div>${chartSVG(chartProduct,chartPeriod)}<div class="chart-labels">${(chartPeriod==='3 meses'?['Agosto','Septiembre','Octubre']:['Semana 1','Semana 2','Semana 3','Semana 4','Semana 5','Semana 6']).map(s=>`<span>${s}</span>`).join('')}</div></div><section class="stats" style="margin-top:23px">${stat('Precio mínimo',money(price*.82),'En el período seleccionado')}${stat('Precio máximo',money(price*1.12),'En el período seleccionado')}${stat('Volumen registrado','24.800 kg','Operaciones de ejemplo','box')}${stat('Operaciones','12','Muestra ilustrativa','deal')}</section><div class="card table-card table-wrap"><table><thead><tr><th>Semana</th><th>Producto</th><th>Precio promedio</th><th>Volumen</th><th>Origen</th></tr></thead><tbody>${[0,1,2].map((n)=>`<tr><td>${chartPeriod==='3 meses'?['Octubre','Septiembre','Agosto'][n]:'Semana '+(6-n)}</td><td>${chartProduct}</td><td>${money(price-n*.12)}</td><td>${(4500+n*600).toLocaleString('es-PE')} kg</td><td>Huaura, Lima</td></tr>`).join('')}</tbody></table></div>`}
function profile(){const seller=state.role==='proveedor';const data=seller?state.providerProfile:state.profile;return heading('La confianza empieza con información clara.','Tu perfil, tu empresa y tus espacios comerciales.')+`<div class="detail-layout"><article class="card" style="padding:0;overflow:hidden"><div class="profile-cover"></div><div class="profile-body"><span class="avatar">${seller?'CR':'BG'}</span><h2>${esc(data.name)}</h2><p>${esc(data.company)} · Lima, Perú</p><div class="row wrap">${badge('Perfil de demostración','gray')}${badge('4,8 / 5 · Ejemplo','amber')}</div><div class="divider"></div><h3>Información comercial</h3><form id="profile-form" style="margin-top:22px"><label>Nombre completo<input name="name" required maxlength="80" value="${esc(data.name)}"></label><label>Empresa<input name="company" required maxlength="100" value="${esc(data.company)}"></label><label>Correo de contacto<input name="email" type="email" required value="${esc(data.email)}"></label><button type="submit" class="btn primary">Guardar cambios ${icon('check')}</button></form></div></article><aside class="stack" style="align-content:start"><article class="card"><h3>Dos roles. Una transición sencilla.</h3><p class="muted" style="font-size:12px">Una empresa puede comprar y vender mediante cuentas vinculadas, con suscripciones independientes.</p><div class="row between"><span class="row">${icon('user')}Cuenta compradora</span>${badge('Vinculada')}</div><div class="divider"></div><div class="row between"><span class="row">${icon('leaf')}Cuenta proveedora</span>${badge('Vinculada')}</div><div style="margin-top:23px">${button('Cambiar a '+(seller?'comprador':'proveedor'),'switch-account','primary full','arrow')}</div><small>El selector de la barra también permite recorrer la vista de administración en esta demo.</small></article><article class="card"><h3>Tu equipo, con acceso ordenado.</h3><p class="muted" style="font-size:12px">Propuesta para la siguiente etapa: accesos individuales para el equipo, permisos por rol y registro de actividad, compartiendo los recursos del plan de la empresa.</p>${badge('Cantidad de accesos por validar','amber')}<p class="muted" style="font-size:11px">Recomendamos empezar con 1 administrador y 2 operadores. Cada persona usa su propio acceso.</p></article><article class="card"><h3>Una reputación que se construye.</h3><p class="muted" style="font-size:12px">Las partes califican al finalizar cada trato. Agrovio complementa la evaluación de confiabilidad antes y después de la transacción.</p><small>El 4,8 mostrado es ilustrativo. Fórmula y ponderación final pendientes.</small></article></aside></div>`}
function plans(){const seller=state.role==='proveedor';const plans=seller?[['Cosecha',69.9,'4 publicaciones por ciclo'],['Crece',99.9,'8 publicaciones por ciclo'],['Pro',149.9,'16 publicaciones por ciclo']]:[['Base',69.9,'10 créditos de conexión'],['Plus',139.9,'30 créditos de conexión'],['Pro',249.9,'75 créditos de conexión']];return heading('Un plan al ritmo de tu negocio.','Planes del landing · Importes sin IGV · Propuesta de presentación.')+`<div class="catalog-head"><div><span class="eyebrow">TU SUSCRIPCIÓN ACTUAL</span><h2 style="margin-top:10px">Agrovio ${esc(seller?state.planSeller:state.planBuyer)}</h2><p>${seller?'Los cupos utilizados no se recuperan al cancelar una publicación.':'Tus créditos vencen cada 30 días desde la apertura de tu cuenta. No se acumulan.'}</p></div>${badge('Ciclo de ejemplo: 21 oct – 20 nov')}</div><div class="plan-cards">${plans.map(([name,price,resource],i)=>`<article class="card plan-card ${i===1?'featured':''}">${i===1?badge('RECOMENDADO'):badge('AGROVIO','gray')}<h3>Agrovio ${name}</h3><small>${['Para empezar a conectar','Para crecer con continuidad','Para un mayor ritmo comercial'][i]}</small><div class="plan-price">${money(price)}<small> / mes</small></div><small>Precio sin IGV</small><ul>${[resource,seller?'Comisión por cierre: 1%':'Toda la oferta del mercado',seller?'Revisión de publicaciones':'Ofertas sin consumo de créditos',seller?'Ofertas y contraofertas':'Desbloqueo por publicación','Soporte del equipo Agrovio'].map(f=>`<li>${icon('check')}${f}</li>`).join('')}</ul>${button((seller?state.planSeller:state.planBuyer)===name?'Plan actual':'Ver detalle',`plan:${name}`,i===1?'primary':'','arrow')}</article>`).join('')}</div><div class="grid2" style="margin-top:25px"><article class="card"><h3>Renovación del plan</h3><p class="muted" style="font-size:12px">El cobro automático estará disponible cuando se integre la pasarela y el usuario asocie una tarjeta. Por ahora no hay credenciales IziPay.</p><div class="notice">${icon('lock')}Sin pasarela conectada. Esta demo no solicita tarjetas ni procesa pagos.</div>${button('Solicitar asistencia con el plan','plan-help','','chat')}</article><article class="card"><h3>${seller?'Sobre tus publicaciones':'¿Necesitas más conexiones?'}</h3><p class="muted" style="font-size:12px">${seller?'Si no renuevas la suscripción, tus publicaciones se eliminan. No existe la opción de pausar.':'Habrá paquetes adicionales de créditos. El precio y las cantidades están por definir; no se muestran importes inventados.'}</p>${badge(seller?'Edición: primeras 24 horas':'Paquetes extra: próximamente','amber')}<div class="divider"></div><small>La demo usa soles. La habilitación de dólares y el tratamiento tributario de comisiones están pendientes de definición.</small></article></div>`}
function movements(){return heading('Tus movimientos, sin puntos ciegos.','Consulta el registro de pagos y comisiones de tus operaciones.',button('Exportar CSV','export','','download'))+`<section class="stats">${stat('Monto del trato',money(22500),'AGR-9223','deal')}${stat('Comisión comprador',money(state.outside?0:225),'1% al cerrar por Agrovio','credit')}${stat('Comisión proveedor',money(state.outside?0:225),'1% al cerrar por Agrovio','credit')}${stat('Neto al proveedor',money(state.outside?22500:22275),'Sin impuestos adicionales de demo','wallet')}</section><div class="card table-card table-wrap"><table><thead><tr><th>Fecha</th><th>Concepto</th><th>Referencia</th><th>Monto</th><th>Estado</th></tr></thead><tbody><tr><td>21 oct, 2026</td><td><strong>Operación de mandarina</strong><small>${state.outside?'Registro externo · Sin comisión':'Pago gestionado por Agrovio'}</small></td><td>AGR-9223</td><td>${money(state.outside?22500:22725)}</td><td>${badge(dealStatus(),state.payment===2?'':'amber')}</td></tr><tr><td>15 oct, 2026</td><td><strong>Operación de fresa</strong><small>Trato completado de ejemplo</small></td><td>AGR-9211</td><td>${money(9696)}</td><td>${badge('Pago liberado')}</td></tr></tbody></table></div><div class="notice">${icon('shield')}Los movimientos son ilustrativos. No se han ejecutado transferencias ni emitido comprobantes.</div>`}
function adminHome(){const pending=state.products.filter(p=>p.status==='En revisión');return heading('Panel de administración','Revisa lo pendiente y entra directamente a la tarea que necesitas resolver.')+'<section class="stats">'+stat('Publicaciones por revisar',pending.length,'Pendientes de aprobación','check')+stat('Usuarios activos',state.adminUsers.filter(u=>u.active).length,'Cuentas del portal','users')+stat('Fondos por liberar',money(state.payment===1?22275:0),'Ingresos confirmados','shield')+stat('Estado del trato',state.outside?'Externo':state.payment===2?'Liberado':state.payment===1?'Recibido':'Pendiente','AGR-9223','wallet')+'</section><section class="admin-work-grid"><article class="card"><div class="section-title"><div><h2>Publicaciones pendientes</h2><small>Comprueba la ficha antes de mostrarla en el mercado.</small></div><a class="btn text-btn" href="#/revision">Ver todas '+icon('arrow')+'</a></div>'+(pending.length?pending.slice(0,4).map(p=>'<div class="review-row"><img src="assets/'+p.image+'" alt=""><div><h3>'+esc(p.name)+'</h3><small>'+esc(p.zone)+' · '+p.volume.toLocaleString('es-PE')+' kg</small></div>'+button('Revisar','review:'+p.id,'','check')+'</div>').join(''):'<div class="empty"><h3>No hay publicaciones pendientes</h3><p>La cola de revisión está al día.</p></div>')+'</article><article class="card payment-overview"><span class="eyebrow">CONTROL DE PAGOS</span><h2>Un paso a la vez,<br>con el ingreso verificado.</h2><div class="money-line"><span>Operación AGR-9223</span><strong>'+money(22500)+'</strong></div><div class="timeline"><div class="timeline-item '+(state.dealStage===3?'done':'')+'"><strong>Confirmaciones del trato</strong><small>'+state.dealStage+' de 3 completadas</small></div><div class="timeline-item '+(state.payment>=1?'done':'')+'"><strong>Verificar ingreso</strong><small>Agrovio confirma el dinero recibido.</small></div><div class="timeline-item '+(state.payment===2?'done':'')+'"><strong>Liberar al proveedor</strong><small>Solo después de confirmar el ingreso.</small></div></div><a href="#/custodia" class="btn primary full">Gestionar pagos '+icon('arrow')+'</a></article></section><section class="admin-shortcuts"><a href="#/usuarios" class="task-card"><span class="task-icon">'+icon('users')+'</span><div><h3>Usuarios y accesos</h3><p>Consulta cuentas y administra su estado.</p></div>'+icon('arrow')+'</a><a href="#/movimientos" class="task-card"><span class="task-icon">'+icon('download')+'</span><div><h3>Movimientos y reportes</h3><p>Revisa importes y descarga el registro.</p></div>'+icon('arrow')+'</a></section>';}
function review(){return heading('Cada publicación empieza con una revisión.','Valida la información antes de incorporarla al mercado.')+`<div class="card table-card table-wrap"><table><thead><tr><th>Producto</th><th>Origen</th><th>Volumen</th><th>Canal</th><th>Estado</th><th>Revisar</th></tr></thead><tbody>${state.products.filter(p=>p.status==='En revisión').map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>AGR-${p.id}</small></td><td>${esc(p.zone)}</td><td>${p.volume.toLocaleString('es-PE')} kg</td><td>${p.id===9005?'WhatsApp':'Plataforma'}</td><td>${badge('En revisión','amber')}</td><td><button data-action="review:${p.id}">Revisar ficha</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><h3>Todo al día</h3><p>No hay publicaciones pendientes de revisión.</p></div></td></tr>'}</tbody></table></div>`}
function users(){return heading('Personas detrás de cada oportunidad.','Vista de cuentas y estado de acceso al portal.')+`<div class="card table-card table-wrap"><table><thead><tr><th>Usuario</th><th>Cuenta</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${state.adminUsers.map((u,i)=>`<tr><td><strong>${u.name}</strong><small>Perfil de ejemplo</small></td><td>${u.company}</td><td>${badge(u.active?'Activo':'Suspendido',u.active?'':'gray')}</td><td><button data-action="user:${i}">${u.active?'Suspender':'Reactivar'}</button></td></tr>`).join('')}</tbody></table></div><div class="notice">${icon('users')}La suspensión es visual en esta demo. El backend deberá controlar sesiones, permisos y acceso a recursos.</div>`}
function custody(){return heading('Fondos claros en cada etapa.','Confirma la recepción antes de liberar el pago al proveedor.')+`<div class="admin-banner row">${icon('shield')}Secuencia: cierre confirmado → transferencia del comprador → ingreso confirmado por Agrovio → pago liberado.</div><div class="card table-card table-wrap"><table><thead><tr><th>Operación</th><th>Paga comprador</th><th>Comisión total</th><th>Recibe proveedor</th><th>Estado</th><th>Acción</th></tr></thead><tbody><tr><td><strong>Mandarina · AGR-9223</strong><small>Bruno Gómez → Diego Torres</small></td><td>${money(state.outside?22500:22725)}</td><td>${money(state.outside?0:450)}</td><td>${money(state.outside?22500:22275)}</td><td>${badge(dealStatus(),state.payment===2?'':'amber')}</td><td>${state.outside?'<small>Acuerdo externo</small>':state.dealStage<3?'<small>Esperando cierre del trato</small>':state.payment===0?button('Confirmar ingreso','receive','primary','check'):state.payment===1?button('Liberar pago','release','primary','arrow'):badge('Liberado')}</td></tr></tbody></table></div><div class="notice">${icon('wallet')}No hay conexión bancaria. Las acciones únicamente cambian estados dentro de esta demostración.</div><a href="#/trato/9223" class="btn text-btn">Ver confirmaciones y detalle ${icon('arrow')}</a>`}
function login(){return`<main class="login" id="content"><section class="login-story"><img src="assets/campo.jpg" alt=""><a class="brand" href="#/inicio"><img src="assets/logo.png" alt=""><span>agrovio</span></a><div class="story-copy"><span class="eyebrow" style="color:#d6e7c4">CONECTAMOS EL VALOR DEL CAMPO</span><h1 style="margin-top:19px">El próximo buen negocio empieza con una conexión.</h1><p>Un espacio para dar visibilidad a tu oferta, negociar y construir relaciones comerciales que crecen.</p><span class="badge" style="background:#ffffff18;color:white">${icon('shield')}Del origen al acuerdo, con más confianza.</span></div><small>© 2026 Agrovio · Portal comercial</small></section><section class="login-form"><div><span class="eyebrow">BIENVENIDO A TU ESPACIO</span><h2 style="margin-top:14px">Volvamos a conectar.</h2><p>Elige un perfil para recorrer la propuesta del portal.</p><div class="login-role">${['comprador','proveedor','admin'].map(r=>`<button class="${loginRole===r?'active':''}" data-action="login-role:${r}">${{comprador:'Comprar',proveedor:'Vender',admin:'Administrar'}[r]}</button>`).join('')}</div><form id="login-form"><label>Correo de demostración<input name="email" type="email" value="demo@agrovio.test" required autocomplete="off"></label><label>Contraseña de demostración<input name="password" type="password" value="demostracion" required autocomplete="off"></label><button class="btn primary full" type="submit">Entrar a la demo ${icon('arrow')}</button></form><small>Acceso simulado. No ingreses credenciales reales. Puedes cambiar de perfil durante el recorrido.</small><div class="divider"></div><button class="text-btn" data-action="onboarding">¿Nuevo en Agrovio? Conoce cómo empezar ${icon('arrow')}</button></div></section></main>`}
function emptyPage(){return`<div class="empty"><h1>No encontramos esta pantalla</h1><p>Vuelve al inicio para continuar el recorrido.</p><a class="btn primary" href="#/inicio">Ir al resumen</a></div>`}
function render(){const [page,id]=current();const allowed=new Set(navItems().map(i=>i[0]).concat(['perfil','planes','login','detalle','trato','publicar','editar']));if(!allowed.has(page)){app.innerHTML=shell(emptyPage(),page);return}let content;switch(page){case'login':app.innerHTML=login();return;case'inicio':content=state.role==='admin'?adminHome():state.role==='proveedor'?sellerHome():buyerHome();break;case'cosecha':case'industrial':case'guardados':content=catalog(page);break;case'detalle':content=productDetail(id);break;case'publicaciones':case'produccion':content=publications(page);break;case'publicar':content=publishForm();break;case'editar':{const p=state.products.find(p=>p.id===Number(id));content=(p?.fresh||p?.status==='Requiere corrección')&&p.status!=='Cancelada'?publishForm(id):emptyPage();break}case'ofertas':content=offers();break;case'tratos':content=deals();break;case'trato':content=dealDetail();break;case'chat':content=chat();break;case'whatsapp':content=whatsappPage();break;case'precios':content=prices();break;case'perfil':content=profile();break;case'planes':content=plans();break;case'movimientos':content=movements();break;case'revision':content=review();break;case'usuarios':content=users();break;case'custodia':content=custody();break;default:content=emptyPage()}
app.innerHTML=shell(content,page);document.title=`${titleFor(page)} · Agrovio`;updateCatalog();}
function switchRole(role,keepDeal=false){state.role=role;save();query='';category='Todas';zone='Todas';mode='Todo';onlySaved=false;if(keepDeal)render();else go('inicio')}
function unlock(id){const p=state.products.find(p=>p.id===id);if(!p)return;if(state.unlocked.includes(id)){toast('Esta publicación ya está desbloqueada.');return}if(state.credits<=0){showModal('Sin créditos disponibles',`<p>Espera la renovación de tu ciclo o consulta por los paquetes adicionales, cuyo precio está pendiente de definición.</p><div class="modal-actions">${button('Ver mi plan','open-plans','primary','credit')}</div>`);return}showModal('Una conexión con nuevas posibilidades.',`<p>Usarás <b>1 crédito</b> para desbloquear el contacto de <b>${esc(p.short)}</b> en la publicación <b>${esc(p.name)} · AGR-${id}</b>.</p><div class="offer-total"><span>Saldo después de conectar</span><strong>${state.credits-1} créditos</strong></div><small>El desbloqueo aplica solo a esta publicación. Las demás publicaciones del proveedor requieren otro crédito.</small><div class="modal-actions">${button('Ahora no','close','',null)}${button('Confirmar · 1 crédito',`unlock-confirm:${id}`,'primary','credit')}</div>`)}
function respond(id){const o=allOffers().find(o=>o.id===id);if(!o)return;const p=state.products.find(p=>p.id===o.productId);showModal('Revisar propuesta',`<h3>${esc(p.name)}</h3><p>Bruno G. · ${o.quantity.toLocaleString('es-PE')} kg · ${money(o.price)} por kg</p><div class="offer-total"><span>Total de la propuesta</span><strong>${money(o.price*o.quantity)}</strong></div><p>${esc(o.conditions||'Sin condiciones adicionales.')}</p>${o.status==='Pendiente'?`<div class="button-group">${button('Aceptar',`offer-accept:${id}`,'primary','check')}${button('Contraofertar',`counter:${id}`,'','deal')}${button('Rechazar',`offer-reject:${id}`,'danger','close')}</div>`:badge(o.status)}`)}
function updateOffer(id,status,price){let o=state.offers.find(o=>o.id===id);if(!o){o=structuredClone(allOffers().find(o=>o.id===id));state.offers.push(o)}o.status=status;if(price)o.price=price;save();closeModal();render();toast('Propuesta actualizada en la demo. No se consumieron créditos.')}
function routeModal(action){closeModal();go(action)}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const [action,arg]=target.dataset.action.split(':');const id=Number(arg);switch(action){case'close':closeModal();break;case'menu':{const open=document.getElementById('sidebar').classList.toggle('open');target.setAttribute('aria-expanded',String(open));break}case'profile':go('perfil');break;case'detail':go('detalle/'+id);break;case'publish':go('publicar');break;case'edit':go('editar/'+id);break;case'save':{const i=state.saved.indexOf(id);if(i<0)state.saved.push(id);else state.saved.splice(i,1);save();const y=scrollY;render();scrollTo(0,y);toast(i<0?'Producto guardado.':'Producto eliminado de tus guardados.');break}case'clear-filters':query='';category='Todas';zone='Todas';mode='Todo';onlySaved=false;sort='recent';render();break;case'search-home':query=document.getElementById('home-search').value;go('cosecha');break;case'home-tab':{document.querySelectorAll('[data-action^="home-tab:"]').forEach(b=>b.classList.toggle('active',b===target));document.getElementById('home-products').innerHTML=state.products.filter(p=>p.status==='Publicada'&&p.type===arg).slice(0,3).map(productCard).join('');break}case'unlock':unlock(id);break;case'unlock-confirm':if(state.credits>0&&!state.unlocked.includes(id)){state.credits--;state.unlocked.push(id);save()}closeModal();render();toast('Conexión habilitada para esta publicación.');break;case'chat':chatId=id;go('chat');break;case'chat-select':chatId=id;render();break;case'respond':respond(id);break;case'offer-accept':updateOffer(id,'Aceptada');break;case'offer-reject':updateOffer(id,'Rechazada');break;case'counter':{const o=allOffers().find(o=>o.id===id);showModal('Una propuesta para acercarse.',`<form id="counter-form" data-id="${id}"><label>Tu precio por kg (S/)<input name="price" type="number" min="0.01" step="0.01" value="${o.price}" required></label><small>Se conserva el volumen de ${o.quantity.toLocaleString('es-PE')} kg.</small><button type="submit" class="btn primary">Enviar contraoferta ${icon('arrow')}</button></form>`);break}case'cancel':showModal('¿Cancelar esta publicación?',`<p>Dejará de estar visible en el mercado. El cupo consumido no se devuelve y no existe la opción de pausar.</p><div class="modal-actions">${button('Mantener publicación','close','',null)}${button('Cancelar publicación',`cancel-confirm:${id}`,'danger','close')}</div>`);break;case'cancel-confirm':{const p=state.products.find(p=>p.id===id);if(p)p.status='Cancelada';save();closeModal();render();toast('Publicación cancelada. El cupo no se recupera.');break}case'confirm-deal':{const valid=(state.dealStage===0&&state.role==='proveedor')||(state.dealStage===1&&state.role==='comprador')||(state.dealStage===2&&state.role==='proveedor');if(valid&&!state.outside){state.dealStage++;save();render();toast(state.dealStage===3?'Trato confirmado por ambas partes.':'Confirmación registrada. Continúa la otra parte.')}break}case'outside':showModal('Registrar un acuerdo por fuera',`<p>Se guardará un registro básico del producto, monto, volumen y contraparte. Agrovio no cobrará comisión ni gestionará el pago.</p><div class="modal-actions">${button('Volver','close','',null)}${button('Registrar acuerdo externo','outside-confirm','primary','check')}</div>`);break;case'outside-confirm':state.outside=true;save();closeModal();render();toast('Acuerdo externo registrado sin comisión.');break;case'custody':go('custodia');break;case'receive':showModal('Confirmar ingreso del comprador',`<p>Operación AGR-9223 · Importe esperado: <b>${money(22725)}</b>.</p><p>En producción, Agrovio verificará el abono antes de registrar este estado. Aquí solo se simula la recepción.</p><div class="modal-actions">${button('Volver','close','',null)}${button('Simular ingreso recibido','receive-confirm','primary','check')}</div>`);break;case'receive-confirm':if(state.role==='admin'&&state.dealStage===3&&!state.outside&&state.payment===0){state.payment=1;save()}closeModal();render();toast('Ingreso confirmado en la demo.');break;case'release':showModal('Liberar pago al proveedor',`<p>El ingreso del comprador ya fue confirmado. Se registrará la liberación de <b>${money(22275)}</b> al proveedor.</p><div class="notice">El monto descuenta la comisión del proveedor de S/ 225. No se hace una transferencia real.</div><div class="modal-actions">${button('Volver','close','',null)}${button('Simular liberación','release-confirm','primary','shield')}</div>`);break;case'release-confirm':if(state.role==='admin'&&state.payment===1){state.payment=2;save()}closeModal();render();toast('Pago liberado en la demo.');break;case'review':{const p=state.products.find(p=>p.id===id);showModal('Revisión de publicación',`<h3>${esc(p.name)}</h3><p>AGR-${id} · ${esc(p.zone)}<br>${p.volume.toLocaleString('es-PE')} kg · ${money(p.price)} por kg<br>${esc(p.quality)}</p><img class="file-preview" src="assets/${p.image}" alt="Producto ilustrativo"><div class="modal-actions">${button('Solicitar correcciones',`rev-reject:${id}`,'','chat')}${button('Aprobar y publicar',`rev-approve:${id}`,'primary','check')}</div>`);break}case'rev-approve':case'rev-reject':if(state.role==='admin'){const p=state.products.find(p=>p.id===id);p.status=action==='rev-approve'?'Publicada':'Requiere corrección';p.fresh=action==='rev-approve';save();closeModal();render();toast(action==='rev-approve'?'Publicación aprobada. Ya aparece en el mercado.':'Se solicitaron correcciones en la demo.')}break;case'user':showModal('Cambiar estado del usuario',`<p>${state.adminUsers[id].active?'Suspender':'Reactivar'} el acceso de <b>${state.adminUsers[id].name}</b>. Esta acción solo modifica el registro visual de la demo.</p><div class="modal-actions">${button('Volver','close','',null)}${button('Confirmar cambio',`user-confirm:${id}`,'primary','check')}</div>`);break;case'user-confirm':if(state.role==='admin'){state.adminUsers[id].active=!state.adminUsers[id].active;save()}closeModal();render();toast('Estado del usuario actualizado.');break;case'switch-account':switchRole(state.role==='proveedor'?'comprador':'proveedor');break;case'login-role':loginRole=arg;render();break;case'notifications':showModal('Lo que está pasando',`<div class="notification-list"><article><span class="badge blue">Negociación</span><h3 style="margin-top:10px">Tienes una nueva respuesta</h3><p>Revisa la conversación de Mandarina W. Murcott.</p>${button('Abrir conversación','notification-chat','','chat')}</article><article><span class="badge amber">Tu plan</span><h3 style="margin-top:10px">Revisa tus recursos disponibles</h3><p>Los créditos vencen cada 30 días. No se acumulan.</p>${button('Ver mi suscripción','open-plans','','credit')}</article></div>`);break;case'notification-chat':routeModal('chat');break;case'open-plans':routeModal('planes');break;case'plan':{const seller=state.role==='proveedor';const prices=seller?{Cosecha:69.9,Crece:99.9,Pro:149.9}:{Base:69.9,Plus:139.9,Pro:249.9};const price=prices[arg];showModal('Agrovio '+esc(arg),`<div class="offer-total"><span>Mensualidad sin IGV</span><strong>${money(price)}</strong></div><p>El cobro y la activación del plan requieren la integración de IziPay. Por ahora puedes preparar una solicitud de asistencia.</p><small>Este prototipo no cambia tu plan ni registra tarjetas.</small><div class="modal-actions">${button('Cerrar','close','',null)}${button('Preparar solicitud','plan-help','primary','chat')}</div>`);break}case'plan-help':showModal('Solicitud de asistencia',`<p>Mensaje sugerido para el equipo de Agrovio:</p><label>Mensaje<textarea id="support-message" readonly>Hola, quisiera recibir asistencia para contratar o renovar mi plan de Agrovio como ${state.role==='proveedor'?'proveedor':'comprador'}. ¿Podrían indicarme los siguientes pasos y el importe final con IGV?</textarea></label><div class="notice">El enlace de WhatsApp se habilitará al confirmar el número oficial de atención. No se ha enviado ningún mensaje.</div>`);break;case'whatsapp':closeModal();go('whatsapp');break;case'help':case'guide':showModal('Tu recorrido por Agrovio',`<div class="timeline"><div class="timeline-item done"><strong>Explora y negocia</strong><small>Comprador: abre el mercado, filtra y presenta una oferta sin gastar créditos.</small></div><div class="timeline-item"><strong>Conecta por publicación</strong><small>Desbloquea con 1 crédito para acceder al contacto y escribir por chat.</small></div><div class="timeline-item"><strong>Publica y revisa</strong><small>Cambia a proveedor para crear una ficha; en administración, apruébala.</small></div><div class="timeline-item"><strong>Confirma y sigue el pago</strong><small>En Mis tratos: proveedor solicita → comprador confirma → proveedor confirma. Luego administración confirma el ingreso y libera el pago.</small></div></div><small>El selector superior permite cambiar de rol. Los cambios permanecen en este navegador. Usa Reiniciar para volver al estado inicial.</small>`);break;case'onboarding':showModal('Un espacio para cada lado del negocio.',`<p>Elige comprar o vender y conoce las herramientas de tu perfil. Una empresa puede tener ambas cuentas vinculadas, con suscripciones separadas.</p><div class="notice">Registro real, validación empresarial y contratación de planes serán parte del backend.</div><div class="modal-actions">${button('Explorar como comprador','start-buyer','primary','arrow')}${button('Explorar como proveedor','start-seller','','leaf')}</div>`);break;case'start-buyer':closeModal();switchRole('comprador');break;case'start-seller':closeModal();switchRole('proveedor');break;case'rate':starChoice=0;showModal('¿Cómo fue trabajar juntos?',`<p>Tu evaluación ayuda a construir relaciones más confiables.</p><div class="rating" role="group" aria-label="Calificación de una a cinco estrellas">${[1,2,3,4,5].map(n=>`<button data-action="star:${n}" aria-label="${n} estrellas" aria-pressed="false">☆</button>`).join('')}</div><label>Comentario (opcional)<textarea id="rating-comment" maxlength="500" placeholder="Cuéntanos cómo fue la operación…"></textarea></label><div class="modal-actions">${button('Guardar calificación','rate-save','primary','check')}</div>`);break;case'star':starChoice=id;modal.querySelectorAll('[data-action^="star:"]').forEach(b=>{const selected=Number(b.dataset.action.split(':')[1])<=id;b.classList.toggle('selected',selected);b.textContent=selected?'★':'☆';b.setAttribute('aria-pressed',String(selected))});break;case'rate-save':if(!starChoice){toast('Selecciona una calificación de 1 a 5.');break}state.rating=starChoice;state.ratingComment=document.getElementById('rating-comment').value;save();closeModal();render();toast('Gracias. Tu evaluación quedó guardada en la demo.');break;case'completed':showModal('Un buen negocio, completado.',`<h3>Fresa San Andreas · AGR-9211</h3><p>2.000 kg × S/ 4,80 = ${money(9600)}<br>Comisión comprador: S/ 96,00<br>Comisión proveedor: S/ 96,00<br>Neto al proveedor: ${money(9504)}</p>${badge('Pago liberado')}<p>Resumen de ejemplo, sin movimientos reales de dinero.</p>`);break;case'export':{const csv='\uFEFFFecha;Referencia;Monto trato;Comision comprador;Comision proveedor;Estado\r\n21/10/2026;AGR-9223;22500;'+(state.outside?'0;0;':'225;225;')+dealStatus()+'\r\n15/10/2026;AGR-9211;9600;96;96;Pago liberado\r\n';const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='agrovio-movimientos-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Movimientos de demostración exportados.');break}case'reset':showModal('Volver al inicio del recorrido',`<p>Se restablecerán los datos locales de esta demostración: créditos, ofertas, guardados, publicaciones y estados.</p><div class="modal-actions">${button('Conservar cambios','close','',null)}${button('Reiniciar demo','reset-confirm','primary','arrow')}</div>`);break;case'reset-confirm':state=defaults();save();query='';category='Todas';zone='Todas';mode='Todo';onlySaved=false;chatId=9000;closeModal();go('inicio');toast('Demo reiniciada.');break}});
document.addEventListener('change',e=>{switch(e.target.id){case'role-select':switchRole(e.target.value,current()[0]==='trato'||(current()[0]==='tratos'&&e.target.value!=='admin'));break;case'category':category=e.target.value;updateCatalog();break;case'zone':zone=e.target.value;updateCatalog();break;case'mode':mode=e.target.value;updateCatalog();break;case'only-saved':onlySaved=e.target.checked;updateCatalog();break;case'sort':sort=e.target.value;updateCatalog();break;case'chart-product':chartProduct=e.target.value;render();break;case'chart-period':chartPeriod=e.target.value;render();break;case'photo-input':{const file=e.target.files[0];if(!file)return;if(file.size>3*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){e.target.value='';toast('Selecciona una imagen JPG, PNG o WebP de hasta 3 MB.');return}const url=URL.createObjectURL(file);const preview=document.getElementById('photo-preview');preview.innerHTML='';const img=document.createElement('img');img.src=url;img.alt='Vista previa de la imagen seleccionada';img.className='file-preview';img.onload=()=>URL.revokeObjectURL(url);preview.append(img);break}}});
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){query=e.target.value;updateCatalog()}if(['offer-price','offer-quantity'].includes(e.target.id)){const a=Number(document.getElementById('offer-price').value),b=Number(document.getElementById('offer-quantity').value);document.getElementById('offer-total').textContent=money(a*b)}});
document.addEventListener('keydown',e=>{if(e.target.id==='home-search'&&e.key==='Enter'){query=e.target.value;go('cosecha')}if(e.key==='Escape'){document.getElementById('sidebar')?.classList.remove('open');document.querySelector('.mobile-toggle')?.setAttribute('aria-expanded','false')}});
document.addEventListener('submit',e=>{const form=e.target;if(!['login-form','offer-form','counter-form','publish-form','chat-form','profile-form'].includes(form.id))return;e.preventDefault();const f=new FormData(form);switch(form.id){case'login-form':switchRole(loginRole);toast('Bienvenido a la demostración de Agrovio.');break;case'offer-form':{const productId=Number(form.dataset.id),p=state.products.find(p=>p.id===productId),price=Number(f.get('price')),quantity=Number(f.get('quantity'));if(!(price>0&&quantity>0&&quantity<=p.volume)){toast('Revisa precio y cantidad disponible.');return}state.offers.push({id:Date.now(),productId,price,quantity,conditions:f.get('conditions'),status:'Pendiente'});save();form.reset();showModal('Tu oferta ya tiene un destino.',`<p>Presentaste una propuesta por <b>${quantity.toLocaleString('es-PE')} kg</b> de ${esc(p.name)} a <b>${money(price)} por kg</b>.</p><div class="offer-total"><span>Total ofertado</span><strong>${money(price*quantity)}</strong></div><div class="notice">${icon('check')}No consumiste créditos. El proveedor revisará tu propuesta.</div><div class="modal-actions">${button('Continuar explorando','close','primary','arrow')}</div>`);break}case'counter-form':updateOffer(Number(form.dataset.id),'Contraoferta enviada',Number(f.get('price')));break;case'publish-form':{const name=String(f.get('name')).trim(),origin=String(f.get('zone')).trim();if(!name||!origin){toast('Completa el nombre del producto y la zona.');return}let p=state.products.find(p=>p.id===Number(form.dataset.id));if(p&&!p.fresh&&p.status!=='Requiere corrección'){toast('La ventana de edición ya finalizó.');return}if(!p){const used=state.products.length;if(used>=8){toast('Alcanzaste los 8 cupos de demostración de tu plan.');return}p={id:Math.max(...state.products.map(p=>p.id))+1,short:'Carlos R.',full:'Carlos Rodríguez',image:'mandarina.jpg',use:'Por evaluar',fresh:false};state.products.push(p)}Object.assign(p,{name,zone:origin,type:f.get('type'),category:f.get('category'),volume:Number(f.get('volume')),price:Number(f.get('price')),mode:f.get('mode'),quality:f.get('quality'),status:'En revisión',fresh:false});p.image=['Berries','Pulpas'].includes(p.category)?'fresa.jpg':'mandarina.jpg';save();go(p.type==='industrial'?'produccion':'publicaciones');toast('Ficha enviada a revisión. Agrovio notificará el resultado.');break}case'chat-form':{if(state.role==='comprador'&&!state.unlocked.includes(chatId)){toast('Desbloquea esta publicación antes de escribir.');return}const m=String(f.get('message')).trim();if(!m)return;(state.messages[chatId]??=[]).push(m);save();render();const list=document.getElementById('messages');list.scrollTop=list.scrollHeight;document.querySelector('#chat-form input')?.focus();break}case'profile-form':state[state.role==='proveedor'?'providerProfile':'profile']={name:String(f.get('name')).trim(),company:String(f.get('company')).trim(),email:String(f.get('email')).trim()};save();render();toast('Información guardada en este navegador.');break}});
window.addEventListener('hashchange',()=>{if(modal.open)closeModal();render();scrollTo(0,0);document.getElementById('content')?.focus({preventScroll:true})});
render();

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.getElementById('content')?.focus();});
document.addEventListener('click',e=>{const sidebar=document.getElementById('sidebar');if(sidebar?.classList.contains('open')&&!e.target.closest('.sidebar,.mobile-toggle')){sidebar.classList.remove('open');document.querySelector('.mobile-toggle')?.setAttribute('aria-expanded','false');}});

document.addEventListener('click',e=>{document.querySelectorAll('.more-navigation[open]').forEach(menu=>{if(!menu.contains(e.target))menu.open=false;});});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.more-navigation[open]').forEach(menu=>menu.open=false);});
